   System.Data.DataTable dt;
private void xrTable2_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 shtoRreshtatNeTabele(xrTable2);
}
    private void shtoRreshtatNeTabele(XRTable xrTable2)
        {
            int i = 0;
            if (dt.Rows.Count > 0)
            {

                for (int j = xrTable2.Rows.Count - 1; j >= 1; j--)
                {
                    xrTable2.Rows.RemoveAt(j);
                }
                Font arial = new Font("Gill Sans MT", 9.00F, FontStyle.Regular);
                PaddingInfo padding = new PaddingInfo(2, 2, 0, 0);
                BorderSide borders = ((BorderSide)(((BorderSide.Left | BorderSide.Top) | BorderSide.Bottom)));
                foreach (System.Data.DataRow row in dt.Rows)
                {
                    XRTableRow rr = new XRTableRow();
                    rr.HeightF = 20f;

                    XRTableCell nr = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(22.63f, "", (i + 1).ToString(), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleLeft, borders, padding);
                    rr.Cells.Add(nr);

                    XRTableCell pershkrimi = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(189.21f, "" , row["PERSHKRIMI"].ToString(), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleLeft, borders, padding);
                    rr.Cells.Add(pershkrimi);

                    XRTableCell njesia = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(77.11f, "" , row["PERSHKRIMNJESIA"].ToString(), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleLeft, borders, padding);
                    rr.Cells.Add(njesia);

                    XRTableCell sasia = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(59.36f, "", String.Format("{0:n2}", row["SASIA"]), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleRight, borders, padding);
                    rr.Cells.Add(sasia);

                    XRTableCell cmimi = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(83.81f, "" , String.Format("{0:n2}", row["CMIMI"]), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleRight, borders, padding);
                    rr.Cells.Add(cmimi);

                    XRTableCell vleraMeTvsh = AlphaWebReports.raporteUtil.shtoQelizeNeTabele(110.89f, "" , String.Format("{0:n2}", row["VLEFTAMETVSH"]), arial, Color.Silver, Color.Transparent, TextAlignment.MiddleRight, BorderSide.All, padding);
                    rr.Cells.Add(vleraMeTvsh);


                    xrTable2.Rows.Insert((i + 1), rr);
                    i++;
                }
            }
        }
private void Rap_FatureShitjeMeArtikujSelmaniA5_3Kopje_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {

            /*ruajme datasetin si nje kopje te vecante, dhe jo si nje reference
		  pastrojme datasetin origjinal dhe shtojme 3 rreshta bosh qe detail band te printohet 3 here
		*/
            dt = ((System.Data.DataSet)(this.DataSource)).Tables[0].Copy();
            ((System.Data.DataSet)(this.DataSource)).Tables[0].Rows.Clear();
            ((System.Data.DataSet)(this.DataSource)).Tables[0].Rows.Add();
            ((System.Data.DataSet)(this.DataSource)).Tables[0].Rows.Add();
            ((System.Data.DataSet)(this.DataSource)).Tables[0].Rows.Add();

            double totalimetvsh = 0;
            for (int i = 0; i < dt.Rows.Count; i++)
            {
  if (dt.Rows[i]["VLEFTAMETVSH"] != DBNull.Value && dt.Rows[i]["VLEFTAMETVSH"] != "")
                totalimetvsh += Convert.ToDouble(dt.Rows[i]["VLEFTAMETVSH"]);
else totalimetvsh  = 0;

            }

            if (dt.Rows.Count > 0)
                setData(dt.Rows[0], totalimetvsh);

}
   private void setData(System.Data.DataRow row, double totalimetvsh)
        {
            double detyrimi;
            double zbritje;

            zbritje = Convert.ToDouble(row["ZBRITJE"]);
            detyrimi = Convert.ToDouble(row["detyrimi"]);
            string monedha = row["MONEDHAKOD"].ToString();
            xrLabel27.Text = String.Format("{0:n2} {1}", (totalimetvsh - zbritje), monedha);
            xrLabel23.Text = String.Format("{0:n2} {1}", (detyrimi - (totalimetvsh - zbritje)), monedha);
            xrLabel4.Text = String.Format("{0:n2} {1}", detyrimi, monedha);
            xrLabel51.Text = row["EMERTIMIKF"].ToString();
            xrLabel22.Text = String.Format("{0} / {1}", row["TELKF"].ToString(), row["FAXKF"].ToString());//[TELKF]+'/'+[FAXKF]
            xrLabel21.Text = row["ADRESAFATURIMIT"].ToString();
            xrLabel59.Text = row["KURSI"].ToString();
            xrLabel13.Text = row["PershkrimiKokaShitje"].ToString();
            xrLabel10.Text = String.Format("{0:dd/MM/yyyy}", Convert.ToDateTime(row["DTDOK"]));
            xrLabel9.Text = row["NRDOK"].ToString();



        }
